css:
.wfp-sim-container {
    padding: 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.wfp-sim-container *, .wfp-sim-container *::before, .wfp-sim-container *::after {
    box-sizing: border-box;
}
.wfp-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #243557 100%);
    color: #ffffff;
    padding: 32px 36px;
    border-radius: 4px;
    margin-bottom: 24px;
    border-bottom: 4px solid #c9a961;
    box-shadow: 0 4px 12px rgba(26,39,68,0.18);
}
.wfp-sim-header-meta {
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: #c9a961;
    margin-bottom: 10px;
    font-weight: 600;
}
.wfp-sim-header h1 {
    font-size: 1.75rem;
    font-weight: 600;
    margin: 0 0 8px 0;
    letter-spacing: -0.01em;
    color: #ffffff;
}
.wfp-sim-subtitle {
    font-size: 0.95rem;
    color: #b8c5d6;
    font-weight: 400;
}
.wfp-sim-period-bar {
    background: #ffffff;
    border: 1px solid #d8dde4;
    border-left: 4px solid #1a2744;
    padding: 14px 22px;
    margin-bottom: 22px;
    font-size: 0.92rem;
    display: flex;
    align-items: center;
    gap: 8px;
    border-radius: 2px;
    color: #4a5568;
}
.wfp-sim-period-bar #currentDay,
.wfp-sim-period-bar #maxPeriods {
    font-weight: 700;
    color: #1a2744;
}
.wfp-sim-period-bar .wfp-sim-period-name {
    margin-left: auto;
    font-weight: 600;
    color: #c9a961;
    text-transform: uppercase;
    font-size: 0.78rem;
    letter-spacing: 0.1em;
    border-left: 1px solid #d8dde4;
    padding-left: 14px;
}
.wfp-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.wfp-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde4;
    border-top: 3px solid #1a2744;
    padding: 20px 18px;
    border-radius: 2px;
    transition: box-shadow 0.2s ease;
}
.wfp-sim-kpi-card:hover {
    box-shadow: 0 4px 14px rgba(26,39,68,0.1);
}
.wfp-sim-kpi-card.wfp-sim-kpi-ceo   { border-top-color: #1a2744; }
.wfp-sim-kpi-card.wfp-sim-kpi-cfo   { border-top-color: #2c6e9b; }
.wfp-sim-kpi-card.wfp-sim-kpi-coo   { border-top-color: #6b4e3d; }
.wfp-sim-kpi-card.wfp-sim-kpi-lid   { border-top-color: #c9a961; }
.wfp-sim-kpi-card.wfp-sim-kpi-audit { border-top-color: #7a3b3b; }
.wfp-sim-kpi-label {
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #1a2744;
    margin-bottom: 4px;
    font-weight: 700;
}
.wfp-sim-kpi-role {
    font-size: 0.7rem;
    color: #98a2b3;
    margin-bottom: 12px;
    font-style: italic;
}
.wfp-sim-kpi-value {
    font-size: 2.4rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1;
    font-variant-numeric: tabular-nums;
}
.wfp-sim-briefing {
    background: #ffffff;
    border: 1px solid #d8dde4;
    padding: 24px 28px;
    margin-bottom: 22px;
    border-radius: 2px;
    border-left: 3px solid #c9a961;
}
.wfp-sim-briefing h3 {
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #c9a961;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.wfp-sim-briefing #briefingText {
    font-size: 0.95rem;
    line-height: 1.65;
    color: #2d3748;
}
.wfp-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dde4;
    padding: 24px 28px;
    margin-bottom: 22px;
    border-radius: 2px;
}
.wfp-sim-controls h3 {
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #1a2744;
    margin: 0 0 18px 0;
    font-weight: 700;
    border-bottom: 1px solid #e4e8ee;
    padding-bottom: 12px;
}
.wfp-sim-decision-row {
    margin-bottom: 18px;
}
.wfp-sim-decision-row label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}
.wfp-sim-decision-row .wfp-sim-decision-hint {
    font-size: 0.8rem;
    color: #6b7585;
    margin-bottom: 10px;
    line-height: 1.5;
}
.wfp-sim-controls select,
.wfp-sim-controls input {
    background: #ffffff;
    border: 1px solid #c4cbd5;
    color: #1a2744;
    border-radius: 2px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
}
.wfp-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.wfp-sim-controls select:focus,
.wfp-sim-controls input:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.12);
}
.wfp-sim-actions {
    margin-top: 22px;
    border-top: 1px solid #e4e8ee;
    padding-top: 18px;
}
.wfp-sim-controls .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
    border-radius: 2px;
    padding: 11px 26px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    font-size: 0.8rem;
    margin-right: 10px;
}
.wfp-sim-controls .btn-primary:hover {
    background: #243557;
    border-color: #243557;
}
.wfp-sim-controls .btn-outline-secondary {
    border-radius: 2px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    border-color: #c4cbd5;
    color: #6b7585;
}
.wfp-sim-history {
    background: #ffffff;
    border: 1px solid #d8dde4;
    padding: 24px 28px;
    margin-bottom: 22px;
    border-radius: 2px;
}
.wfp-sim-history h3 {
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: #1a2744;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.wfp-sim-history table {
    margin-bottom: 0;
    font-size: 0.86rem;
    width: 100%;
}
.wfp-sim-history table thead th {
    background: #f4f5f7;
    color: #1a2744;
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 700;
    border-bottom: 2px solid #1a2744;
    padding: 10px 12px;
}
.wfp-sim-history table tbody td {
    padding: 9px 12px;
    border-bottom: 1px solid #eef0f3;
    color: #2d3748;
    font-variant-numeric: tabular-nums;
}
.wfp-sim-history table tbody tr:hover {
    background: #fafbfc;
}
.wfp-sim-chart {
    background: #ffffff;
    border: 1px solid #d8dde4;
    padding: 24px 28px;
    margin-bottom: 22px;
    border-radius: 2px;
    height: 400px;
}
@media (max-width: 768px) {
    .wfp-sim-container { padding: 14px; }
    .wfp-sim-header { padding: 22px 22px; }
    .wfp-sim-header h1 { font-size: 1.35rem; }
    .wfp-sim-kpi-value { font-size: 1.9rem; }
    .wfp-sim-period-bar { flex-wrap: wrap; }
    .wfp-sim-period-bar .wfp-sim-period-name { margin-left: 0; padding-left: 0; border-left: none; flex-basis: 100%; margin-top: 6px; }
    .wfp-sim-chart { height: 300px; }
    .wfp-sim-briefing, .wfp-sim-controls, .wfp-sim-history, .wfp-sim-chart { padding: 18px 18px; }
}

/* FIX v1.1.0 - completion / cabinet-decision screen */
.wfp-sim-completion { padding: 8px 4px; text-align: center; }
.wfp-sim-completion-heading {
    font-size: 12px; letter-spacing: .08em; text-transform: uppercase;
    color: #6b7585; margin-bottom: 6px;
}
.wfp-sim-completion-verdict {
    font-size: 24px; font-weight: 700; color: #1a2744; margin-bottom: 14px;
}
.wfp-sim-completion-score {
    display: inline-flex; align-items: baseline; gap: 8px;
    padding: 8px 16px; background: #f4f5f7; border-radius: 8px; margin-bottom: 18px;
}
.wfp-sim-completion-score span { font-size: 13px; color: #6b7585; }
.wfp-sim-completion-score strong { font-size: 20px; color: #1a2744; }
.wfp-sim-completion-insights-heading {
    font-size: 12px; letter-spacing: .06em; text-transform: uppercase;
    color: #6b7585; margin-bottom: 8px;
}
.wfp-sim-completion-insights {
    list-style: none; padding: 0; margin: 0 auto; max-width: 620px; text-align: left;
}
.wfp-sim-completion-insights li {
    padding: 10px 14px; margin-bottom: 8px; background: #fbfbfc;
    border-left: 3px solid #c9a961; border-radius: 4px; color: #2b3446; font-size: 14px;
}

js:
(function() {
    'use strict';

    class WfpAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Workforce Planning Under Strategic Shifts';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ceoScore: 50,
                    cfoScore: 50,
                    cooScore: 50,
                    lidScore: 50,
                    auditScore: 50,
                    compositeHistory: [],
                    ceoHistory: [],
                    cfoHistory: [],
                    cooHistory: [],
                    lidHistory: [],
                    auditHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decompose_depth: 'moderate',
                    memo_structure: 'combined',
                    memo_length: 14
                };
            }
            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation && window.mySimulation.state ? window.mySimulation.state : state);
            }, 250);
        }

        validateDecisions(decisions) {
            var round = window.mySimulation.state.currentPeriod;
            if (round === 1) {
                var dd = document.getElementById('decomposeDepthInput');
                var ms = document.getElementById('memoStructureInput');
                var ml = document.getElementById('memoLengthInput');
                if (dd) decisions.decompose_depth = dd.value;
                if (ms) decisions.memo_structure = ms.value;
                if (ml) decisions.memo_length = parseInt(ml.value);
            } else if (round === 2) {
                var cd = document.getElementById('capabilitiesDepthInput');
                var rr = document.getElementById('regimeRigorInput');
                var ac = document.getElementById('attritionCorrelationInput');
                if (cd) decisions.capabilities_depth = parseInt(cd.value);
                if (rr) decisions.regime_rigor = rr.value;
                if (ac) decisions.attrition_correlation = ac.value;
            } else {
                var sr = document.getElementById('sourcingRenewablesInput');
                var sc = document.getElementById('sourcingCustomerInput');
                var sa = document.getElementById('sourcingAgentInput');
                var sm = document.getElementById('sourcingMethaneInput');
                var ur = document.getElementById('upstreamRetireInput');
                var cc = document.getElementById('controlsCostInput');
                if (sr) decisions.sourcing_renewables = sr.value;
                if (sc) decisions.sourcing_customer = sc.value;
                if (sa) decisions.sourcing_agent = sa.value;
                if (sm) decisions.sourcing_methane = sm.value;
                if (ur) decisions.upstream_retire = parseInt(ur.value);
                if (cc) decisions.controls_cost = cc.value;
            }
            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var ceoDelta = 0, cfoDelta = 0, cooDelta = 0, lidDelta = 0, auditDelta = 0;
            var feedback = '';

            if (round === 1) {
                if (d.decompose_depth === 'shallow') {
                    ceoDelta -= 12; lidDelta -= 18;
                    feedback += 'Shallow decomposition; the cabinet sees rhetoric where it expected named capabilities. ';
                } else if (d.decompose_depth === 'moderate') {
                    ceoDelta += 6; lidDelta += 6;
                    feedback += 'Moderate decomposition; defensible at role-cluster level but thin on seniority. ';
                } else {
                    ceoDelta += 22; lidDelta += 18; auditDelta += 4;
                    feedback += 'Deep decomposition; the memo names capabilities role-by-role with year-by-year demand. ';
                }

                if (d.memo_structure === 'combined') {
                    ceoDelta += 14; lidDelta += 14; cooDelta -= 4;
                    feedback += 'Build-list and retire-list sit in one document; the cabinet must endorse both together. ';
                } else {
                    ceoDelta -= 12; lidDelta -= 12; cooDelta += 6;
                    feedback += 'Build-list and retire-list split into two documents; the polite version Don Eugenio warned against. ';
                }

                if (d.memo_length === 10) {
                    lidDelta += 4; ceoDelta -= 6;
                    feedback += '10 pages: Don Eugenio reads it but the substance feels thin. ';
                } else if (d.memo_length === 14) {
                    lidDelta += 22; ceoDelta += 12;
                    feedback += '14 pages matches the Lead Independent Director attention budget exactly. ';
                } else {
                    lidDelta -= 22; ceoDelta -= 6;
                    feedback += '20 pages: Don Eugenio reads only the first fourteen and stops. ';
                }
            } else if (round === 2) {
                if (d.capabilities_depth === 4) {
                    cfoDelta -= 10; auditDelta -= 16; ceoDelta -= 6;
                    feedback += 'Only four capabilities at depth; the cabinet cannot stress-test the rest. ';
                } else if (d.capabilities_depth === 8) {
                    cfoDelta += 16; auditDelta += 22; ceoDelta += 16;
                    feedback += 'Eight load-bearing capabilities at full depth; the matrix is defensible. ';
                } else {
                    cfoDelta -= 6; auditDelta += 4; ceoDelta -= 12;
                    feedback += 'Fourteen capabilities attempted; depth is uneven and breadth dilutes the signal. ';
                }

                if (d.regime_rigor === 'central') {
                    ceoDelta -= 18; cfoDelta -= 8;
                    feedback += 'A single central case with hand-waves at the alternates; cabinet cannot stress-test. ';
                } else if (d.regime_rigor === 'balanced') {
                    ceoDelta += 6; cfoDelta += 6;
                    feedback += 'Balanced regime treatment; central case detailed, alternates noted. ';
                } else {
                    ceoDelta += 22; cfoDelta += 14; auditDelta += 10;
                    feedback += 'All three regimes modeled at equal rigor; cabinet can stress-test capability by capability. ';
                }

                if (d.attrition_correlation === 'yes') {
                    cfoDelta += 12; auditDelta += 16;
                    feedback += 'Attrition modeled as regime-correlated; matches the Luis Felipe agent-stack outputs. ';
                } else {
                    auditDelta -= 12; cfoDelta -= 4;
                    feedback += 'Attrition modeled as flat across regimes; CFO Mariana catches this in two minutes. ';
                }
            } else {
                var bestSourcing = {
                    sourcing_renewables: 'build',
                    sourcing_customer:   'buy',
                    sourcing_agent:      'build',
                    sourcing_methane:    'buy'
                };
                var keys = ['sourcing_renewables', 'sourcing_customer', 'sourcing_agent', 'sourcing_methane'];
                for (var i = 0; i < keys.length; i++) {
                    var k = keys[i];
                    if (d[k] === bestSourcing[k]) { ceoDelta += 6; cfoDelta += 4; }
                    else if (d[k] === 'borrow') { ceoDelta -= 5; cfoDelta -= 3; }
                    else if (d[k] === 'bot') { ceoDelta += 1; auditDelta -= 4; }
                    else { ceoDelta += 2; }
                }

                var r = d.upstream_retire;
                if (r === 40) {
                    cooDelta += 24; ceoDelta -= 14;
                    feedback += '40 retire seats: COO Rodrigo signs comfortably; CEO Andrés sees a soft plan that does not match Sofía model. ';
                } else if (r === 80) {
                    cooDelta += 8; ceoDelta += 8;
                    feedback += '80 retire seats: middle ground; nobody fully comfortable, nobody walking out. ';
                } else if (r === 120) {
                    cooDelta -= 8; ceoDelta += 24; lidDelta += 10;
                    feedback += '120 retire seats: matches the Sofía model; cabinet endorses if the dignity terms hold. ';
                } else {
                    cooDelta -= 24; ceoDelta += 4;
                    feedback += '160 retire seats: COO Rodrigo will not sign for the operational risk envelope. ';
                }

                if (d.controls_cost === 'yes') {
                    auditDelta += 28; cfoDelta += 10;
                    feedback += 'Controls cost surfaced explicitly; Doña Luisa engaged, audit trail named. ';
                } else {
                    auditDelta -= 24;
                    feedback += 'No controls cost line; Doña Luisa finds the gap inside thirty seconds. ';
                }
            }

            ds.ceoScore   = Math.max(0, Math.min(100, ds.ceoScore   + ceoDelta));
            ds.cfoScore   = Math.max(0, Math.min(100, ds.cfoScore   + cfoDelta));
            ds.cooScore   = Math.max(0, Math.min(100, ds.cooScore   + cooDelta));
            ds.lidScore   = Math.max(0, Math.min(100, ds.lidScore   + lidDelta));
            ds.auditScore = Math.max(0, Math.min(100, ds.auditScore + auditDelta));

            var composite = Math.round((ds.ceoScore + ds.cfoScore + ds.cooScore + ds.lidScore + ds.auditScore) / 5);

            ds.compositeHistory.push(composite);
            ds.ceoHistory.push(ds.ceoScore);
            ds.cfoHistory.push(ds.cfoScore);
            ds.cooHistory.push(ds.cooScore);
            ds.lidHistory.push(ds.lidScore);
            ds.auditHistory.push(ds.auditScore);

            // FIX v1.1.0 — expose a score the Express reporting layer can read.
            // results_utils.php::express_resolveDomainScore() looks for
            // domainState.performance.overallScore first, then a top-level numeric
            // `score`. The original wrote neither, so the instructor results panel
            // rendered an empty "-". Composite is the 5-voice cabinet mean (0-100);
            // scoring math is unchanged.
            ds.score = composite;
            ds.performance = { overallScore: composite, grade: this._grade(composite) };

            var self = this;
            setTimeout(function() {
                if (window.mySimulation && window.mySimulation.state) {
                    self._updateBriefing(window.mySimulation.state);
                }
            }, 500);

            return {
                period: state.currentPeriod,
                ceoDelta: ceoDelta,
                cfoDelta: cfoDelta,
                cooDelta: cooDelta,
                lidDelta: lidDelta,
                auditDelta: auditDelta,
                composite: composite,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('ceoDisplay',   'domainState.ceoScore',   (v) => Math.round(v));
            uiManager.bind('cfoDisplay',   'domainState.cfoScore',   (v) => Math.round(v));
            uiManager.bind('cooDisplay',   'domainState.cooScore',   (v) => Math.round(v));
            uiManager.bind('lidDisplay',   'domainState.lidScore',   (v) => Math.round(v));
            uiManager.bind('auditDisplay', 'domainState.auditScore', (v) => Math.round(v));

            var self = this;
            setTimeout(function() {
                if (window.mySimulation && window.mySimulation.state) {
                    self._updateBriefing(window.mySimulation.state);
                }
            }, 300);
        }

        getChartConfig() {
            return {
                cabinetChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'CEO Andrés',  data: [], borderColor: '#1a2744', backgroundColor: 'rgba(26,39,68,0.06)',  borderWidth: 3, fill: false, tension: 0.25, pointRadius: 4 },
                            { label: 'CFO Mariana', data: [], borderColor: '#2c6e9b', backgroundColor: 'rgba(44,110,155,0.06)', borderWidth: 2, fill: false, tension: 0.25, pointRadius: 3 },
                            { label: 'COO Rodrigo', data: [], borderColor: '#6b4e3d', backgroundColor: 'rgba(107,78,61,0.06)',  borderWidth: 2, fill: false, tension: 0.25, pointRadius: 3 },
                            { label: 'Don Eugenio', data: [], borderColor: '#c9a961', backgroundColor: 'rgba(201,169,97,0.06)', borderWidth: 2, fill: false, tension: 0.25, pointRadius: 3 },
                            { label: 'Doña Luisa',  data: [], borderColor: '#7a3b3b', backgroundColor: 'rgba(122,59,59,0.06)',  borderWidth: 2, fill: false, tension: 0.25, pointRadius: 3 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cabinet Endorsement by Round', font: { size: 14, weight: '600' }, color: '#1a2744' },
                            legend: { position: 'bottom', labels: { color: '#1a2744', font: { size: 11 } } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, title: { display: true, text: 'Score (0–100)', color: '#6b7585' }, grid: { color: '#eef0f3' }, ticks: { color: '#6b7585' } },
                            x: { grid: { display: false }, ticks: { color: '#6b7585' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.ceoHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                cabinetChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.ceoHistory },
                        { data: ds.cfoHistory },
                        { data: ds.cooHistory },
                        { data: ds.lidHistory },
                        { data: ds.auditHistory }
                    ]
                }
            };
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };
        }

        _grade(score) {
            if (score >= 75) return 'A';
            if (score >= 60) return 'B';
            if (score >= 45) return 'C';
            return 'D';
        }

        getPerformanceSummary(history) {
            var t = this._t();
            var ds = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.domainState : null;
            var periods = history ? history.length : 0;
            if (!ds) return { totalPeriods: periods };
            var composite = Math.round((ds.ceoScore + ds.cfoScore + ds.cooScore + ds.lidScore + ds.auditScore) / 5);
            var verdictKey = 'verdict_sentback';
            if (composite >= 75) verdictKey = 'verdict_commitment';
            else if (composite >= 60) verdictKey = 'verdict_reservations';
            else if (composite >= 45) verdictKey = 'verdict_conditional';

            var insights = [];
            if (ds.ceoScore   < 50) insights.push(t('insight_ceo_low'));
            if (ds.cfoScore   < 50) insights.push(t('insight_cfo_low'));
            if (ds.cooScore   < 50) insights.push(t('insight_coo_low'));
            if (ds.lidScore   < 50) insights.push(t('insight_lid_low'));
            if (ds.auditScore < 50) insights.push(t('insight_audit_low'));
            if (insights.length === 0) insights.push(t('insight_success'));

            return {
                totalPeriods: periods,
                composite: composite,
                overallScore: composite,
                performance: t(verdictKey),
                verdictKey: verdictKey,
