        getHint(state, results) {
            var ds = state.domainState;
            var scores = [
                { name: 'ceo',   value: ds.ceoScore   },
                { name: 'cfo',   value: ds.cfoScore   },
                { name: 'coo',   value: ds.cooScore   },
                { name: 'lid',   value: ds.lidScore   },
                { name: 'audit', value: ds.auditScore }
            ];
            scores.sort(function(a, b) { return a.value - b.value; });
            var lowest = scores[0];
            if (lowest.value < 35) {
                return window.mySimulation.t('hint_' + lowest.name + '_low');
